{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Loganin, a glycoside with a glucose moiety, showed the lowest brain levels among tissues after systemic dosing in rats, demonstrating that glycoside-containing structures can have poor BBB penetration; this supports fail for the large glycoside-based query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tobramycin, a highly polar aminoglycoside oligosaccharide, produced very low or unmeasurable CSF concentrations in neonates, showing that large polyhydroxylated carbohydrate-based molecules do not achieve meaningful CNS access; this transfers to the query's large cyclic sugar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Me-4FDG, a glucose derivative, did not cross the BBB in rats because it is not a GLUT1 substrate; the query is much larger than a monosaccharide and would not be expected to use GLUT1 or related small-sugar transporters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "3OMG crosses the BBB only via GLUT1-mediated transport; this carrier accepts small monosaccharides, so the much larger cyclic oligosaccharide query is unlikely to share this permeation mechanism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "THP, a small glucose derivative, rapidly entered the brain after IV injection in rabbits; however, its small size and simple monosaccharide structure make this permeable result poorly transferable to the large cyclic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly polar cyclic oligosaccharide with multiple hydroxypropyl ether groups. Direct evidence from glycosides, aminoglycosides, and glucose derivatives indicates that large or non-transported carbohydrate structures do not achieve meaningful BBB/CNS access, while small monosaccharide permeation is transporter-dependent and not applicable to this much larger scaffold. Therefore the query is predicted to fail meaningful CNS access after systemic administration.",
  "evidence_gaps": [
    "No direct experimental record for a cyclodextrin-like oligosaccharide in the evidence set.",
    "No quantitative brain/plasma or CSF exposure data for the query molecule.",
    "Potential uptake via endocytosis or other non-classical routes is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

